const worldFilters = (values, selected) => `<div class="tw-world-filters" role="group" aria-label="Filter results">${values.map(v=>`<button type="button" data-filter="${v}" aria-pressed="${selected===v}">${v}</button>`).join('')}</div>`;
const tokenLabel = a => a.coin?.name&&a.coin?.ticker?`${esc(a.coin.name)} · $${esc(a.coin.ticker)}`:'Token not configured';
const card = a => `<a class="tw-agent" href="#/agent/${encodeURIComponent(a.id)}"><div class="tw-card-character"><img data-character="${esc(a.character)}" alt="${esc(a.name)} character"></div><div class="tw-card-title"><h3>${esc(a.name)}</h3><span class="tw-status" data-status="${esc(statusText(a))}">${esc(statusText(a))}</span></div><p>${tokenLabel(a)}</p><div class="tw-agent-bottom">${esc(state.config.strategies.find(s => s.id === a.strategy)?.name || a.strategy)}</div><span class="tw-world-card-action">VIEW AGENT →</span></a>`;
const activity = () => state.events.length ? `<ol class="tw-events">${state.events.slice(0, 8).map(e => `<li><span class="tw-event-icon">${icon(e.type === 'minted' ? 'check' : 'plus')}</span><div><p>${esc(e.message)}</p><time>${stamp(e.createdAt)}</time></div><a href="#/agent/${encodeURIComponent(e.agentId)}" aria-label="View agent">View</a></li>`).join('')}</ol>` : `<div class="tw-quiet"><h3>Your next move starts here.</h3><p>Your workspace activity will appear here.</p></div>`;
function home(page) {
  page.innerHTML='<section class="ov-workspace-hero" aria-label="3D workspace"></section><div class="ov-data-sections"></div>';
  const map=page.querySelector('.ov-workspace-hero'),dashboard=page.querySelector('.ov-data-sections');
  let world;
  try{world=renderWorkspaceMap(map,{onAction:role=>{if(role==='trade')dashboard.querySelector('.tw-overview-feed')?.scrollIntoView({behavior:'smooth',block:'start'});else if(role==='shill')share();else location.hash=role==='launch'?'#/launch':'#/how';}});scenes.push(world);}
  catch(error){map.insertAdjacentHTML('beforeend','<p role="alert">3D workspace could not load. Reload to retry.</p>');console.error('Workspace map failed',error);}
  scenes.push(mountOverview(dashboard,{getSession:()=>state.session?.address,onNetwork:network=>world?.updateActivity(network)}));
}
function share() { const url = new URL('https://x.com/intent/post'); url.searchParams.set('text', 'Building my own agent workspace with TEKKTEAM.'); window.open(url.href, '_blank', 'noopener,noreferrer'); }
function agents(page) {
  if(location.hash==='#/agents/new'){createAgentPage(page);return;}
  const agents=state.agents;
  page.innerHTML = `<div class="tw-world tw-world-agents">${worldHero('YOUR AI WORKFORCE','BUILD A TEAM.<br><em>LET THEM WORK.</em>','Create autonomous agents, configure their strategy and track their work.','frank','<a class="tw-world-cta primary" href="#/agents/new">CREATE AGENT <span>↗</span></a>','<a class="tw-world-cta secondary" href="#agent-activity">VIEW ACTIVITY <span>→</span></a>')}<div class="tw-world-metrics">${worldMetric('TOTAL AGENTS',agents.length)}${worldMetric('ACTIVE',agents.filter(a=>a.tradingStatus==='WORKING').length,'positive')}${worldMetric('PAUSED',agents.filter(a=>a.tradingStatus==='PAUSED').length)}${worldMetric('DRAFT',agents.filter(a=>a.tradingStatus==='DRAFT').length)}</div><section class="tw-world-section" id="agent-activity"><div class="tw-world-section-head"><div><span class="tw-world-eyebrow">WORKFORCE ROSTER</span><h2>YOUR AGENTS <small>${agents.length}</small></h2></div></div><div class="tw-world-toolbar">${worldFilters(['ALL','ACTIVE','PAUSED','DRAFT'],'ALL')}<label class="tw-world-search">${icon('search')}<input id="tw-search" type="search" placeholder="Search agents or tokens" aria-label="Search agents"></label></div><div class="tw-agent-grid directory" id="tw-directory"></div></section></div>`;
  let filter='ALL';
  const paint = () => { const query = $('#tw-search').value.toLowerCase(); const list = agents.filter(a => `${a.name} ${a.coin?.name??''} ${a.coin?.ticker??''}`.toLowerCase().includes(query) && (filter==='ALL'||(filter==='ACTIVE'?a.tradingStatus==='WORKING':a.tradingStatus===filter))); $('#tw-directory').innerHTML = list.length ? list.map(card).join('') : `<div class="tw-world-empty"><img src="${characterPortraitUrl('frank')}" alt=""><div><span class="tw-world-eyebrow">NO RESULTS</span><h3>${query||filter!=='ALL'?'NO AGENTS FOUND':'YOUR WORKFORCE IS EMPTY'}</h3><p>${query||filter!=='ALL'?'Try another search or filter.':'Create your first AI agent and put it to work.'}</p>${query||filter!=='ALL'?'':'<a class="tw-world-cta primary" href="#/agents/new">CREATE AGENT →</a>'}</div></div>`; hydrateCharacters($('#tw-directory')); };
  $('#tw-search').oninput = paint;page.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.filter;page.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));paint();}); paint();
}
function tokens(page) {
 const list=state.agents.filter(a=>a.coin?.name&&a.coin?.ticker),records=new Map(),version=routeVersion;
 const tokenCard=a=>{const r=records.get(a.id),live=r?.confirmed&&r.status==='Success',image=a.coin?.image;return `<article class="tw-token-card"><a class="tw-token-art" href="#/agent/${encodeURIComponent(a.id)}">${/^https:\/\//.test(image??'')?'<img src="'+esc(image)+'" alt="'+esc(a.coin.name)+' token image" loading="lazy">':icon('tokens')}</a><div class="tw-token-card-body"><span class="tw-status" data-status="${live?'LIVE':'DRAFT'}">${live?'LIVE':!r?'CHECKING':r.error?'UNAVAILABLE':r.signature?'PENDING':r.status==='Idle'?'DRAFT':esc(r.status)}</span><h3>${esc(a.coin.name)}</h3><strong>$${esc(a.coin.ticker)}</strong><p>AGENT · ${esc(a.name)}</p>${live?'<p class="tw-token-mint">CA '+esc(short(r.mint))+'</p><a class="tw-text-link" href="https://pump.fun/coin/'+encodeURIComponent(r.mint)+'" target="_blank" rel="noopener noreferrer">VIEW TOKEN '+icon('external')+'</a>':''}<a class="tw-world-card-action" href="#/agent/${encodeURIComponent(a.id)}">VIEW AGENT →</a></div></article>`;};
 page.innerHTML=`<div class="tw-world tw-world-tokens">${worldHero('TOKEN DESK','YOUR TOKENS.<br><em>ONE COMMAND CENTER.</em>','Track tokens connected to your agents and launches.','satoshi','<a class="tw-world-cta primary" href="#/launch">LAUNCH TOKEN <span>↗</span></a>')}<div class="tw-world-metrics" id="tw-token-metrics"></div><section class="tw-world-section"><div class="tw-world-section-head"><div><span class="tw-world-eyebrow">ASSET DESK</span><h2>YOUR TOKENS <small>${list.length}</small></h2></div></div><div class="tw-world-toolbar">${worldFilters(['ALL','ACTIVE','LAUNCHED','DRAFT'],'ALL')}<label class="tw-world-search">${icon('search')}<input id="tw-search" type="search" placeholder="Search tokens or agents" aria-label="Search tokens"></label></div><div class="tw-token-grid" id="tw-token-directory"></div></section></div>`;
 let filter='ALL';
 const paint=()=>{if(version!==routeVersion)return;const live=a=>records.get(a.id)?.confirmed&&records.get(a.id)?.status==='Success',query=$('#tw-search',page).value.toLowerCase();const liveCount=list.filter(live).length;$('#tw-token-metrics',page).innerHTML=worldMetric('TOTAL TOKENS',list.length)+worldMetric('LAUNCHED',liveCount,'positive')+worldMetric('DRAFT / OTHER',list.length-liveCount);const shown=list.filter(a=>`${a.coin.name} ${a.coin.ticker} ${a.name}`.toLowerCase().includes(query)&&(filter==='ALL'||(filter==='DRAFT'?!live(a):live(a))));$('#tw-token-directory',page).innerHTML=shown.length?shown.map(tokenCard).join(''):`<div class="tw-world-empty"><img src="${characterPortraitUrl('satoshi')}" alt=""><div><span class="tw-world-eyebrow">TOKEN DESK</span><h3>${query||filter!=='ALL'?'NO TOKENS FOUND':'NO TOKENS YET'}</h3><p>${query||filter!=='ALL'?'Try another search or filter.':'Your agent tokens will appear here.'}</p><a class="tw-world-cta primary" href="#/launch">LAUNCH TOKEN →</a></div></div>`;};
 $('#tw-search',page).oninput=paint;page.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.filter;page.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));paint();});
 paint();for(const a of list)fetch('/api/pump-launch/status?agentId='+encodeURIComponent(a.id)).then(async r=>{if(!r.ok)throw Error('Launch status unavailable');return r.json();}).then(r=>{records.set(a.id,r);paint();}).catch(()=>{records.set(a.id,{error:true});paint();});
}
async function launch(page) {
  const version=routeVersion;
  page.innerHTML='<p role="status">Loading your agents…</p>';
  try{
    await refresh();if(version!==routeVersion)return;
    paintWallet();
    const heading=head('TOKEN LAUNCH','Choose your agent.','Launch your token from its Agent Detail page.');
    if(!state.session){page.innerHTML=heading+empty('Connect your wallet','Connect the owner wallet to view your agents.',false)+'<button class="tw-button primary" id="tw-launch-connect">Connect wallet</button>';$('#tw-launch-connect').onclick=openWallet;return;}
    if(state.agents.some(a=>a.creator!==state.session.address))throw Error('Agent owner mismatch. Reconnect your owner wallet.');
    page.innerHTML=heading+(state.agents.length?'<div class="tw-agent-grid directory">'+state.agents.map(card).join('')+'</div>':empty('No agents yet','Create an agent first to launch a token.',false)+'<button class="tw-button primary" id="tw-create-agent">Create agent</button>');
    if($('#tw-create-agent'))$('#tw-create-agent').onclick=createAgentDialog;
    hydrateCharacters(page);
  }catch(e){if(version!==routeVersion)return;page.innerHTML=empty('Could not load agents',esc(e.message),false)+'<button class="tw-button" id="tw-launch-retry">Try again</button>';$('#tw-launch-retry').onclick=()=>launch(page);}
}
