  page.innerHTML = `<div class="tw-world tw-world-characters">${worldHero('CHARACTER LAB','BUILD THE FACE<br><em>OF YOUR WORKFORCE.</em>','Choose the characters representing your agents.','cupsey','<a class="tw-world-cta primary" href="#character-gallery">EXPLORE CREW <span>↓</span></a>')}<div class="tw-world-metrics">${worldMetric('TOTAL CHARACTERS',crew.length)}${worldMetric('ASSIGNED',crew.filter(c=>assigned(c).length).length,'positive')}${worldMetric('AVAILABLE',crew.filter(c=>!assigned(c).length).length)}</div><section class="tw-world-section" id="character-gallery"><div class="tw-world-section-head"><div><span class="tw-world-eyebrow">MEET THE CREW</span><h2>CHARACTER ROSTER <small>${crew.length}</small></h2></div></div><div class="tw-character-gallery">${crew.map((c,i) => `<article style="--character-color:${esc(c.color)}"><span class="tw-eyebrow">CREW / 0${i+1}</span><div class="tw-model" data-model="${esc(c.id)}"></div><div class="tw-character-meta"><div><h2>${esc(c.name)}</h2><p>${esc(c.role)}</p></div><span class="tw-status" data-status="${assigned(c).length?'ACTIVE':'DRAFT'}">${assigned(c).length?'ASSIGNED':'AVAILABLE'}</span></div><p class="tw-character-assignment">${assigned(c).length?'AGENT · '+esc(assigned(c).map(a=>a.name).join(', ')):'READY FOR YOUR WORKFORCE'}</p>${assigned(c).length?`<a class="tw-world-card-action" href="#/agent/${encodeURIComponent(assigned(c)[0].id)}">VIEW AGENT →</a>`:`<a class="tw-world-card-action" href="#/skins/assign/${encodeURIComponent(c.id)}">CHOOSE CHARACTER →</a>`}</article>`).join('')}</div></section></div>`;
  document.querySelectorAll('[data-model]').forEach(host => { try { scenes.push(createBoss(host, { skin: host.dataset.model })); } catch { host.innerHTML = `<img src="${characterPortraitUrl(host.dataset.model)}" alt="${esc(state.config.characters.find(c=>c.id===host.dataset.model)?.name || 'Agent')} character">`; } });
